using System.Collections;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.BattleActions;

public class SearchDiceOnPoolAction : BattleAction
{
	[Header("SearchDiceOnPoolAction Specifics")]
	[SerializeField]
	protected PlayerDiceInventoryData poolToChooseFrom;

	[SerializeField]
	private PlayerDiceInventoryData discardPool;

	[SerializeField]
	private PlayerDiceInventoryDataEvent OnShowChooseDiceOnPoolCanvas;

	[SerializeField]
	protected VoidEvent OnHideSearchDiceOnPoolCanvas;

	[SerializeField]
	private BattleActionReference searchDiceOnPoolActionReference;

	[SerializeField]
	private ReshuffleDiscardedDicesHandler reshuffleDiscardedDicesHandler;

	[SerializeField]
	private GameObject searchPanelPrefab;

	[SerializeField]
	private GameObjectReference searchPanelReference;

	[SerializeField]
	private CameraReference dicePreviewCameraReference;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (CheckImmobilized((diceOwnerEnum == DiceOwnerEnum.PLAYER) ? ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject : null))
		{
			return false;
		}
		if (IsVoidSeek())
		{
			return poolToChooseFrom.GetDicesAmount() > 0;
		}
		if (poolToChooseFrom.GetDicesAmount() <= 0)
		{
			return discardPool.GetDicesAmount() > 0;
		}
		return true;
	}

	public bool IsVoidSeek()
	{
		return poolToChooseFrom == discardPool;
	}

	private bool CheckImmobilized(GameObject source)
	{
		if (!ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			return false;
		}
		return ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerImmobilized();
	}

	public override void Cast(GameObject source)
	{
		if (!CheckImmobilized(source))
		{
			DiceOwnerEnum diceOwnerEnum = DiceOwnerEnum.PLAYER;
			if (!ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
			{
				diceOwnerEnum = DiceOwnerEnum.COMPANION;
			}
			if (CheckConditionToBeCasted(playerHand: false, diceOwnerEnum))
			{
				AfterCheckConditionToBeCasted();
			}
		}
	}

	protected virtual void AfterCheckConditionToBeCasted()
	{
		if (ReferenceSingleton<BattleHandler>.Instance.CorruptedSoulActivated)
		{
			ReferenceSingleton<BattleHandler>.Instance.CorruptedSoulActivated = false;
			return;
		}
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(BeforeSearchDiceOnPoolActionCoroutine());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator BeforeSearchDiceOnPoolActionCoroutine()
	{
		yield return InvokeAlternatives.WaitForFrames(ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(SearchDiceOnPoolActionCoroutine());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator SearchDiceOnPoolActionCoroutine()
	{
		yield return InvokeAlternatives.WaitOneFrame();
		if (poolToChooseFrom != discardPool && poolToChooseFrom.GetDicesAmountWithoutDiceJustPlayed() == 0 && !ReferenceSingleton<DiceDrawingHandler>.Instance.ShufflingDice)
		{
			yield return ReshuffleDiscardIntoBag();
		}
		else if (BeforeShowSearchDicePanelCheck())
		{
			yield return new WaitForSeconds(0.4f);
			ShowSearchDicePanel();
		}
	}

	protected virtual bool BeforeShowSearchDicePanelCheck()
	{
		if (poolToChooseFrom.GetDicesAmountWithoutDiceJustPlayed() == 0)
		{
			return false;
		}
		if (!ReferenceSingleton<BattleHandler>.Instance.CurrentCorruptedAnimals.IsAnyEnemyActive())
		{
			return false;
		}
		return true;
	}

	private IEnumerator ReshuffleDiscardIntoBag()
	{
		ReferenceSingleton<DiceDrawingHandler>.Instance.ShufflingDice = true;
		yield return reshuffleDiscardedDicesHandler.ReshuffleDices();
		ReferenceSingleton<DiceDrawingHandler>.Instance.ShufflingDice = false;
		yield return new WaitForSeconds(0.4f);
		if (BeforeShowSearchDicePanelCheck())
		{
			ShowSearchDicePanel();
		}
	}

	private void ShowSearchDicePanel()
	{
		if (poolToChooseFrom.GetDicesAmountWithoutDiceJustPlayed() == 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.NoFrame);
			return;
		}
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ChooseDiceOnPoolState);
		searchPanelReference.value = ReferenceSingleton<PoolHandler>.Instance.GetObject(searchPanelPrefab.name);
		if (searchPanelReference.value == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(searchPanelPrefab);
			searchPanelReference.value = ReferenceSingleton<PoolHandler>.Instance.GetObject(searchPanelPrefab.name);
			searchPanelReference.value.GetComponent<Canvas>().worldCamera = dicePreviewCameraReference.value;
		}
		searchDiceOnPoolActionReference.SetValue(this);
		PlayerDiceInventoryData playerDiceInventoryData = Object.Instantiate(poolToChooseFrom);
		playerDiceInventoryData._OnDicePoolChange = null;
		playerDiceInventoryData._OnDicePoolChangeNoShake = null;
		playerDiceInventoryData.RemoveAllJustPlayedDice();
		OnShowChooseDiceOnPoolCanvas.Raise(playerDiceInventoryData);
	}

	public virtual void DiceChosen(Dice dice)
	{
	}
}
